import { useCallback, useEffect, useState } from "react";
import { Inbox, Loader2 } from "lucide-react";
import { forecastingApi, type ForecastTask, type TaskStatus } from "../api/forecasting";
import { extractErrorMsg } from "../utils/format";
import { ErrorBanner, ScreenFrame, Segmented, fmtDate } from "./forecasting/ui";

/** Analytics → Opportunity Inbox (SUPERVISOR+). Work items from
 *  _tb_SOTask. Tasks are generated by the weekly opportunity detector
 *  (Phase 6); this screen works them: start, snooze, resolve, dismiss. */

const TYPE_LABEL: Record<string, string> = {
  VISIT_CUSTOMER: "Visit customer",
  INVESTIGATE_SHORTFALL: "Investigate shortfall",
  RESCUE_SHORTFALL: "Rescue shortfall",
  REACTIVATE_CUSTOMER: "Reactivate customer",
  NEW_PRODUCT_PUSH: "New product push",
  OFFER_SUBSTITUTE: "Offer substitute",
  ESCALATE_CREDIT: "Escalate credit",
  UPSELL_OPPORTUNITY: "Upsell",
  RIGHT_SIZE_ORDER: "Right-size order",
  REVIEW_FLAGGED_TARGET: "Review flagged target",
  REVIEW_FORECAST_DRIFT: "Review forecast drift",
};

const PRIORITY_CLASS = {
  HIGH: "bg-red-100 text-red-700 border-red-200",
  MED: "bg-amber-100 text-amber-800 border-amber-200",
  LOW: "bg-gray-100 text-gray-600 border-gray-200",
};

type StatusFilter = "open" | "closed" | "all";

export function OpportunityInboxScreen({ onBack }: { onBack?: () => void }) {
  const [filter, setFilter] = useState<StatusFilter>("open");
  const [mine, setMine] = useState(false);
  const [tasks, setTasks] = useState<ForecastTask[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState<number | null>(null);
  const [resolving, setResolving] = useState<{ id: number; status: TaskStatus; notes: string } | null>(null);

  const load = useCallback(() => {
    setTasks(null);
    forecastingApi
      .listTasks({ status: filter, mine })
      .then(setTasks)
      .catch((e) => {
        setTasks([]);
        setError(extractErrorMsg(e, "Failed to load tasks."));
      });
  }, [filter, mine]);

  useEffect(load, [load]);

  async function setStatus(id: number, status: TaskStatus, notes?: string) {
    setBusy(id);
    setError(null);
    try {
      const updated = await forecastingApi.updateTask(id, { status, resolution_notes: notes || null });
      const stillVisible =
        filter === "all" ||
        (filter === "open") === ["OPEN", "IN_PROGRESS", "SNOOZED"].includes(updated.status);
      setTasks((prev) =>
        (prev ?? []).flatMap((t) => (t.id !== id ? [t] : stillVisible ? [updated] : [])),
      );
      setResolving(null);
    } catch (e) {
      setError(extractErrorMsg(e, "Failed to update task."));
    } finally {
      setBusy(null);
    }
  }

  const today = new Date().toISOString().slice(0, 10);

  return (
    <ScreenFrame
      icon={<Inbox className="w-4 h-4 text-teal-600" />}
      title="Opportunity Inbox"
      onBack={onBack}
      maxWidth="900px"
      toolbar={
        <>
          <label className="flex items-center gap-1 text-xs text-gray-700">
            <input type="checkbox" checked={mine} onChange={(e) => setMine(e.target.checked)} />
            Assigned to me
          </label>
          <Segmented<StatusFilter>
            value={filter}
            onChange={setFilter}
            options={[
              { value: "open", label: "Open" },
              { value: "closed", label: "Closed" },
              { value: "all", label: "All" },
            ]}
          />
        </>
      }
    >
      <ErrorBanner message={error} onClose={() => setError(null)} />
      <div className="flex-1 min-h-0 overflow-auto space-y-2">
        {tasks === null && (
          <div className="text-center text-gray-400 py-8"><Loader2 className="w-4 h-4 animate-spin inline" /></div>
        )}
        {tasks?.length === 0 && (
          <div className="bg-white rounded border p-6 text-center text-sm text-gray-500">
            Nothing here. Tasks are created by the weekly opportunity detector and by flagged scenario targets.
          </div>
        )}
        {tasks?.map((t) => {
          const overdue = t.due_date < today && ["OPEN", "IN_PROGRESS"].includes(t.status);
          const closed = t.status === "RESOLVED" || t.status === "DISMISSED";
          return (
            <div key={t.id} className={`bg-white rounded border shadow-sm p-3 ${closed ? "opacity-70" : ""}`}>
              <div className="flex items-start gap-2">
                <span className={`inline-flex rounded border px-1.5 py-0.5 text-[10px] font-semibold ${PRIORITY_CLASS[t.priority]}`}>
                  {t.priority}
                </span>
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-semibold text-gray-900">{t.title}</div>
                  <div className="text-[11px] text-gray-500 mt-0.5 flex flex-wrap gap-x-3">
                    <span>{TYPE_LABEL[t.task_type] ?? t.task_type}</span>
                    {t.customer_account && <span>Customer {t.customer_account}</span>}
                    {t.stock_code && <span>Product {t.stock_code}</span>}
                    {t.route && <span>Route {t.route}</span>}
                    {t.scenario_id != null && <span>Scenario #{t.scenario_id}</span>}
                    {t.assigned_to && <span>→ {t.assigned_to}</span>}
                  </div>
                </div>
                <div className={`text-[11px] whitespace-nowrap ${overdue ? "text-red-600 font-semibold" : "text-gray-500"}`}>
                  Due {fmtDate(t.due_date)}
                </div>
              </div>
              {t.description && <p className="text-xs text-gray-700 mt-2 whitespace-pre-line">{t.description}</p>}
              {closed && (
                <p className="text-[11px] text-gray-500 mt-2">
                  {t.status === "RESOLVED" ? "Resolved" : "Dismissed"} by {t.resolved_by ?? "—"} on {fmtDate(t.resolved_at)}
                  {t.resolution_notes ? ` — ${t.resolution_notes}` : ""}
                </p>
              )}

              {resolving?.id === t.id ? (
                <div className="mt-2 flex gap-2">
                  <input
                    autoFocus
                    className="flex-1 border border-gray-300 rounded px-2 py-1 text-xs"
                    placeholder={resolving.status === "RESOLVED" ? "What was done? (optional)" : "Why dismiss? (optional)"}
                    value={resolving.notes}
                    onChange={(e) => setResolving({ ...resolving, notes: e.target.value })}
                    onKeyDown={(e) => e.key === "Enter" && setStatus(t.id, resolving.status, resolving.notes)}
                  />
                  <button className="btn btn-primary text-xs" disabled={busy === t.id}
                          onClick={() => setStatus(t.id, resolving.status, resolving.notes)}>
                    {resolving.status === "RESOLVED" ? "Resolve" : "Dismiss"}
                  </button>
                  <button className="btn btn-ghost text-xs" onClick={() => setResolving(null)}>Cancel</button>
                </div>
              ) : (
                <div className="mt-2 flex gap-1 text-xs">
                  <span className="text-gray-500 mr-1 self-center">{t.status.replace("_", " ").toLowerCase()}</span>
                  {!closed && t.status !== "IN_PROGRESS" && (
                    <button className="px-2 py-0.5 rounded border hover:bg-gray-50" disabled={busy === t.id}
                            onClick={() => setStatus(t.id, "IN_PROGRESS")}>Start</button>
                  )}
                  {!closed && t.status !== "SNOOZED" && (
                    <button className="px-2 py-0.5 rounded border hover:bg-gray-50" disabled={busy === t.id}
                            onClick={() => setStatus(t.id, "SNOOZED")}>Snooze</button>
                  )}
                  {!closed && (
                    <>
                      <button className="px-2 py-0.5 rounded border border-emerald-300 text-emerald-700 hover:bg-emerald-50"
                              disabled={busy === t.id}
                              onClick={() => setResolving({ id: t.id, status: "RESOLVED", notes: "" })}>Resolve</button>
                      <button className="px-2 py-0.5 rounded border text-gray-600 hover:bg-gray-50" disabled={busy === t.id}
                              onClick={() => setResolving({ id: t.id, status: "DISMISSED", notes: "" })}>Dismiss</button>
                    </>
                  )}
                  {closed && (
                    <button className="px-2 py-0.5 rounded border hover:bg-gray-50" disabled={busy === t.id}
                            onClick={() => setStatus(t.id, "OPEN")}>Reopen</button>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </ScreenFrame>
  );
}
